      .map(id => state.chats[id])
      .filter(Boolean)
      .sort((a, b) => {
        const timeA = new Date(a.lastMessageAt || a.updated_at || 0).getTime()
        const timeB = new Date(b.lastMessageAt || b.updated_at || 0).getTime()
        return timeB - timeA
      })
  },
